<script>
(() => {
  'use strict';
  const NS = 'wyxy';
  const PROTOCOL_VERSION = 1;
  const GIRLS = {
    linwanqiu: '林晚秋', jiangling: '江铃', sunian: '苏念',
    fangtangtang: '方糖糖', guyunlei: '顾云蕾',
  };
  const app = document.getElementById('wyxy-app');
  const $$ = sel => app.querySelector(`[data-bind="$${sel}"]`);
  const setView = v => { app.dataset.view = v; };
  const uid = () => (crypto.randomUUID ? crypto.randomUUID() : 'id-' + Math.random().toString(36).slice(2));

  // ---- 依赖探测（契约 §4.7）----
  const hasTH = () => typeof window.getLastMessageId === 'function' && typeof window.createChatMessages === 'function';
  const hasMvu = () => typeof window.Mvu === 'object' && window.Mvu && typeof window.Mvu.getMvuData === 'function';

  // ---- GameStateAdapter：只读快照（契约 §4.4，组件不直接摸楼层 API）----
  const adapter = {
    lastError: null,
    snapshot() {
      try {
        const lastId = window.getLastMessageId();
        let stat = null;
        try {
          const mvu = window.Mvu.getMvuData({ type: 'message', message_id: 'latest' });
          if (mvu && mvu.stat_data && mvu.stat_data.world) stat = mvu.stat_data;
        } catch (e) { /* 楼层无帧则回退 chat 域 */ }
        if (!stat) {
          try {
            const mvu = window.Mvu.getMvuData({ type: 'chat' });
            if (mvu && mvu.stat_data && mvu.stat_data.world) stat = mvu.stat_data;
          } catch (e) { /* 保持 null */ }
        }
        let story = '';
        if (lastId > 0) {
          const msgs = window.getChatMessages(lastId);
          if (msgs && msgs[0] && msgs[0].role === 'assistant') story = stripSystem(msgs[0].message);
          else if (lastId > 1) {
            const prev = window.getChatMessages(lastId - 1);
            if (prev && prev[0] && prev[0].role === 'assistant') story = stripSystem(prev[0].message);
          }
        }
        return { lastId, stat, story };
      } catch (e) {
        this.lastError = e;
        return null;
      }
    },
  };
  const stripSystem = t => String(t || '')
    .replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/g, '')
    .replace(/<结算[^>]*\/>/g, '')
    .replace(/<(?:UpdateVariable|结算)[^]*$$/, '')
    .trim();

  // ---- chat-service：全部楼层写操作收口（契约 §4.1）----
  const chatService = {
    async sendAction(text, meta) {
      await window.createChatMessages(
        [{ role: 'user', message: text, data: { same_floor_ui: { protocol_version: PROTOCOL_VERSION, ...meta } } }],
        { refresh: 'affected' },
      );
      await window.triggerSlash('/trigger');
    },
  };

  // ---- 可恢复 UI 状态：开局草稿存 chat 域 same_floor_ui（契约 §4.4）----
  const draftStore = {
    async save(draft) {
      try {
        await window.insertOrAssignVariables(
          { same_floor_ui: { protocol_version: PROTOCOL_VERSION, wizard_draft: draft } },
          { type: 'chat' },
        );
      } catch (e) { /* 草稿非关键路径 */ }
    },
    load() {
      try {
        const v = window.getVariables({ type: 'chat' });
        const d = v && v.same_floor_ui && v.same_floor_ui.wizard_draft;
        return d && typeof d === 'object' ? d : null;
      } catch (e) { return null; }
    },
  };

  // ---- busy 链（契约 §4.2：事件+超时对账）----
  let busyTimer = null;
  function setBusy(on, text) {
    app.dataset.busy = on ? '1' : '';
    if (text) $$('busy-text').textContent = text;
    clearTimeout(busyTimer);
    if (on) busyTimer = setTimeout(() => { setBusy(false); showError('main-error', '生成超时或事件漏收，已按当前楼层对账。'); refresh(); }, 120000);
  }
  function showError(slot, msg) {
    const el = $$(slot);
    if (!el) return;
    el.textContent = msg || '';
    el.dataset.show = msg ? '1' : '';
  }

  // ---- 渲染 ----
  function renderMain(snap) {
    const s = snap.stat;
    if (s && s.world) {
      $$('day').textContent = s.world.day;
      $$('ap').textContent = s.world.ap;
      $$('pressure').textContent = s.world.parent_pressure;
      $$('pressure-bar').style.width = Math.max(0, Math.min(100, +s.world.parent_pressure || 0)) + '%';
      $$('hint').textContent = s.world.ap <= 0 ? '行动点已耗尽——结束今天，进入夜晚。' : '';
      const apEmpty = s.world.ap <= 0;
      for (const b of app.querySelectorAll('[data-act="talk"],[data-act="drill"]')) b.disabled = apEmpty;
    } else {
      $$('hint').textContent = '（变量尚未初始化——等待第一轮生成完成）';
    }
    $$('story').textContent = snap.story || '';
  }

  let refreshQueued = false;
  function refresh() {
    if (refreshQueued) return;
    refreshQueued = true;
    setTimeout(() => {
      refreshQueued = false;
      const snap = adapter.snapshot();
      if (!snap) { showError('main-error', '读取聊天状态失败：' + (adapter.lastError && adapter.lastError.message || '未知错误')); return; }
      if (snap.lastId === 0) { setView('wizard'); restoreDraft(); }
      else { setView('main'); renderMain(snap); }
    }, 150);
  }

  // ---- 开局向导（契约 §3.2 / §4.3：草稿→预览不写状态→确认冻结→真实开场消息）----
  const wizardForm = () => $$('wizard-form');
  function readDraft() {
    const f = new FormData(wizardForm());
    return { 理念: f.get('理念') || '平衡', 难度: f.get('难度') || '标准', 关注: f.get('关注') || 'linwanqiu' };
  }
  function openingMessage(d) {
    return `【开局设定】理念=$${d.理念}；难度=$${d.难度}；首位关注=$${GIRLS[d.关注] || d.关注}\n\n` +
      `我在园长办公室签完最后一份交接文件。窗外，操场上五个身影按规定间距站着早训队列。` +
      `我把「$${GIRLS[d.关注] || ''}」的档案抽出来放在桌面最上层——今天，先从她开始。`;
  }
  function restoreDraft() {
    const d = draftStore.load();
    if (!d) return;
    for (const [k, v] of Object.entries(d)) {
      const input = wizardForm().querySelector(`input[name="$${k}"][value="$${v}"]`);
      if (input) input.checked = true;
    }
  }
  let confirming = false;
  async function confirmOpening() {
    if (confirming) return; // 防重复提交（契约 §7）
    confirming = true;
    const btn = app.querySelector('[data-act="confirm"]');
    btn.disabled = true;
    showError('wizard-error', '');
    try {
      const d = readDraft(); // 确认冻结
      const before = window.getLastMessageId();
      if (before !== 0) throw new Error('聊天状态已变化，请刷新后重试');
      await chatService.sendAction(openingMessage(d), { action_id: uid(), type: '开局设定', opening: d });
      setView('main');
      setBusy(true, '开局生成中……');
    } catch (e) {
      showError('wizard-error', '开局提交失败：' + (e && e.message || e) + '（草稿已保留，可重试）');
      btn.disabled = false;
      confirming = false;
    }
  }

  // ---- 行动（契约 §4.2 主链）----
  const ACTION_TEXT = {
    talk: k => `我把$${GIRLS[k]}单独叫到谈话室。没有记录本，没有评分表——只是谈谈。`,
    drill: k => `我安排$${GIRLS[k]}参加下午的纪律训练，按机构标准流程执行。`,
    endday: () => `今天的安排到此为止。我在值班日志上签字，宣布熄灯就寝。`,
  };
  const ACTION_META = { talk: '个别谈话', drill: '纪律训练', endday: '结束今天' };
  async function sendAction(kind, girlKey) {
    try {
      setBusy(true, '生成中……');
      await chatService.sendAction(
        ACTION_TEXT[kind](girlKey),
        { action_id: uid(), type: ACTION_META[kind], target: girlKey || null },
      );
    } catch (e) {
      setBusy(false);
      showError('main-error', '行动发送失败：' + (e && e.message || e));
    }
  }

  // ---- 选人 Modal ----
  let pickerKind = null;
  function openPicker(kind) {
    pickerKind = kind;
    $$('picker-title').textContent = kind === 'talk' ? '与谁谈话？' : '安排谁训练？';
    const list = $$('picker-list');
    list.textContent = '';
    const snap = adapter.snapshot();
    for (const [key, name] of Object.entries(GIRLS)) {
      const finished = snap && snap.stat && snap.stat.girls && snap.stat.girls[key] && snap.stat.girls[key].结局;
      const b = document.createElement('button');
      b.type = 'button';
      b.textContent = name + (finished ? '（已离园）' : '');
      b.disabled = !!finished;
      b.addEventListener('click', () => { $$('picker').close(); sendAction(pickerKind, key); });
      list.appendChild(b);
    }
    $$('picker').showModal();
  }

  // ---- 事件接线 ----
  function wire() {
    app.addEventListener('click', ev => {
      const act = ev.target && ev.target.closest && ev.target.closest('[data-act]');
      if (!act) return;
      switch (act.dataset.act) {
        case 'preview': {
          const d = readDraft();
          $$('preview').textContent = '开场消息预览（只读，不写入状态）：\n\n' + openingMessage(d);
          app.querySelector('[data-act="confirm"]').disabled = false;
          break;
        }
        case 'confirm': confirmOpening(); break;
        case 'talk': openPicker('talk'); break;
        case 'drill': openPicker('drill'); break;
        case 'endday': sendAction('endday'); break;
        case 'picker-cancel': $$('picker').close(); break;
      }
    });
    wizardForm().addEventListener('change', () => {
      draftStore.save(readDraft());
      app.querySelector('[data-act="confirm"]').disabled = true; // 改动后须重新预览
      $$('preview').textContent = '';
    });
    app.querySelector('[data-act="escape"]').addEventListener('change', ev => {
      try { window.eventEmit(`$${NS}:escape`, { show_native: !!ev.target.checked }); } catch (e) { /* bridge 缺席时静默 */ }
    });
    // 生成结束 → 对账刷新；busy 解锁（契约 §4.2）
    try {
      window.eventOn(window.iframe_events.GENERATION_ENDED, () => { setBusy(false); refresh(); });
      window.eventOn(window.tavern_events.CHARACTER_MESSAGE_RENDERED, () => refresh());
      window.eventOn(window.tavern_events.CHAT_CHANGED, () => refresh());
    } catch (e) { /* 事件面缺席时依赖超时对账 */ }
    // 心跳 → bridge 维持 presentation mode（契约 §4.5）
    setInterval(() => { try { window.eventEmit(`$${NS}:heartbeat`, {}); } catch (e) {} }, 3000);
  }

  // ---- 启动：仅凭持久数据重建（契约 §4.4 红线）----
  function boot(tries) {
    if (!hasTH()) {
      if (tries > 40) { setView('broken'); $$('broken-reason').textContent = '未检测到酒馆助手 API（iframe 注入失败或扩展未启用）。'; return; }
      setTimeout(() => boot(tries + 1), 250);
      return;
    }
    if (!hasMvu()) {
      if (tries > 40) { setView('broken'); $$('broken-reason').textContent = '酒馆助手已就绪，但 MVU 变量框架未加载（请检查卡内 MVU 加载器脚本与网络）。'; return; }
      setTimeout(() => boot(tries + 1), 250);
      return;
    }
    // 关注对象选项（含默认选中）
    const focus = $$('focus-opts');
    focus.textContent = '';
    let first = true;
    for (const [key, name] of Object.entries(GIRLS)) {
      const label = document.createElement('label');
      const input = document.createElement('input');
      input.type = 'radio'; input.name = '关注'; input.value = key; input.checked = first; first = false;
      label.appendChild(input); label.appendChild(document.createTextNode(name));
      focus.appendChild(label);
    }
    wire();
    refresh();
  }
  boot(0);
})();
</script>
